import { Injectable } from '@angular/core';
import { PurchaseOrder } from '../pages/purchase-order/purchase-order';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';
import { party } from '../pages/party/party';
import { environment } from '../environments/environments';
@Injectable({
  providedIn: 'root'
})
export class PoService {
  private ApiUrl = `${environment.apiUrl}/purchaseorder`;

  constructor(private http: HttpClient) {}

  getPO(): Observable<PurchaseOrder[]>{
    return this.http.get<PurchaseOrder[]>(`${this.ApiUrl}`);
  }

CreatePO(po: PurchaseOrder): Observable<PurchaseOrder> {
  const backendPayload = {
    SupplierId: po.supplierId,
    Supplier: po.supplier
      ? {
          id: po.supplier.id,
          name: po.supplier.name,
          address: po.supplier.address,
          gstin: po.supplier.gstin,
          state: po.supplier.state,
          stateCode: po.supplier.stateCode ?? 0,
          phone: po.supplier.phone,
          email: po.supplier.email,
        }
      : null,

    Address: po.address || '',
    OrderDate: po.orderDate,
    GrandTotal: po.grandTotal || 0,
    PlaceOfSupply: po.placeOfSupply || '',
    TermsOfDelivery: po.termsOfDelivery || '',
    TermsOfPayment: po.termsOfPayment || '',

    Invoice: {
      Id: 0,
      InvoiceDate: po.orderDate.split('T')[0],
      PlaceOfSupply: po.placeOfSupply || '',
      TermsOfDelivery: po.termsOfDelivery || '',
      TermsOfPayment: po.termsOfPayment || '',
      PurchaseOrderId: 0,
    },

    Items: po.items.map(i => ({
      Id: i.id || 0,
      RawMaterialId: i.rawMaterialsId,
      RawMaterialDto: i.rawMaterialDto
        ? { id: i.rawMaterialDto.id, name: i.rawMaterialDto.name, price: i.rawMaterialDto.price }
        : null,
      MakeId: i.makeId,
      Unit: i.unit || 'Carton',
      Rate: i.rate || 0,
      Per: i.per || 1,
      Quantity: i.quantity || 0,
      Amount: i.amount || 0,
      PurchaseOrderId: 0,
    })),
  };

  console.log('sending payload', backendPayload);
  return this.http.post<PurchaseOrder>(`${this.ApiUrl}/create`, backendPayload);
}

  getPOById(id: number): Observable<PurchaseOrder> {
  return this.http.get<PurchaseOrder>(`${this.ApiUrl}/${id}`);
}

  editPO(id: number, Po: PurchaseOrder): Observable<PurchaseOrder> {
  return this.http.put<PurchaseOrder>(`${this.ApiUrl}/edit/${id}`, Po);
}
}

